const h = params.height;
const w = h * 0.38;
const railR = h * 0.018;
const deckT = h * 0.055;
const zDeck = 0;
const chuteColor = params.color;
const frameColor = api.mix(params.color, '#17385f', 0.78);
const accentColor = api.mix(params.color, '#ffd34e', 0.72);
const darkColor = '#263442';
const chuteMat = { preset: 'plastic', color: chuteColor, roughness: 0.34 };
const frameMat = { preset: 'metal', color: frameColor, metalness: 0.58, roughness: 0.38 };
const accentMat = { preset: 'plastic', color: accentColor, roughness: 0.42 };
const gripMat = { preset: 'rubber', color: darkColor, roughness: 0.82 };
const deckMat = { preset: 'metal', color: frameColor, metalness: 0.45, roughness: 0.62 };
api.add(api.box(w * 1.34, deckT, w * 1.15).translate(0, h, zDeck), deckMat);
api.add(api.box(w * 1.16, h * 0.025, w * 0.96).translate(0, h + deckT * 0.58, zDeck), gripMat);
const postX = w * 0.56;
const postZ = w * 0.42;
for (let sx = -1; sx <= 1; sx += 2) {
  for (let sz = -1; sz <= 1; sz += 2) {
    api.add(api.cylinder(railR * 1.22, railR * 1.22, h, 10).translate(sx * postX, h * 0.5, sz * postZ), frameMat);
  }
}
for (let sx = -1; sx <= 1; sx += 2) {
  api.add(api.tube([[sx * postX, h + deckT, -postZ], [sx * postX, h * 1.42, -postZ], [sx * postX, h * 1.42, postZ * 0.18]], railR, 8), frameMat);
}
api.add(api.tube([[-postX, h * 1.42, -postZ], [postX, h * 1.42, -postZ]], railR, 8), frameMat);
const ladderBottomZ = -h * 0.72;
const ladderTopZ = -postZ;
const ladderTopY = h + deckT;
const ladderBottomY = h * 0.08;
const ladderDx = w * 0.48;
for (let sx = -1; sx <= 1; sx += 2) {
  api.add(api.tube([[sx * ladderDx, ladderBottomY, ladderBottomZ], [sx * ladderDx, ladderTopY, ladderTopZ], [sx * ladderDx, h * 1.38, -postZ]], railR * 1.1, 8), frameMat);
}
const rungCount = 7;
for (let i = 0; i < rungCount; i++) {
  const t = i / (rungCount - 1);
  const ry = ladderBottomY + (ladderTopY - ladderBottomY) * t;
  const rz = ladderBottomZ + (ladderTopZ - ladderBottomZ) * t;
  api.add(api.cylinder(railR * 0.82, railR * 0.82, ladderDx * 2, 8).rotate(0, 0, 90).translate(0, ry, rz), accentMat);
}
const chuteStartZ = postZ + w * 0.18;
const chuteLen = h * 1.48;
const chuteWidth = w * 1.08;
const segments = 14;
const panelDepth = chuteLen / segments * 1.09;
for (let i = 0; i < segments; i++) {
  const t0 = i / segments;
  const t1 = (i + 1) / segments;
  const tm = (t0 + t1) * 0.5;
  const z0 = chuteStartZ + chuteLen * t0;
  const z1 = chuteStartZ + chuteLen * t1;
  const y0 = h * (1 - t0) * (1 - t0) + h * 0.08;
  const y1 = h * (1 - t1) * (1 - t1) + h * 0.08;
  const angle = Math.atan2(y0 - y1, z1 - z0) * 180 / Math.PI;
  const cy = (y0 + y1) * 0.5;
  const cz = (z0 + z1) * 0.5;
  api.add(api.box(chuteWidth, h * 0.035, panelDepth).rotate(angle, 0, 0).translate(0, cy, cz), chuteMat);
  api.collider({ kind: 'box', halfExtents: [chuteWidth * 0.5, h * 0.026, panelDepth * 0.5], offset: [0, cy, cz], rotation: [angle, 0, 0] });
}
const leftPath = [];
const rightPath = [];
for (let i = 0; i <= segments; i++) {
  const t = i / segments;
  const z = chuteStartZ + chuteLen * t;
  const y = h * (1 - t) * (1 - t) + h * 0.08 + h * 0.16;
  leftPath.push([-chuteWidth * 0.53, y, z]);
  rightPath.push([chuteWidth * 0.53, y, z]);
}
api.add(api.tube(leftPath, railR * 1.18, 8), accentMat);
api.add(api.tube(rightPath, railR * 1.18, 8), accentMat);
for (let i = 0; i <= segments; i += 2) {
  const t = i / segments;
  const z = chuteStartZ + chuteLen * t;
  const floorY = h * (1 - t) * (1 - t) + h * 0.08;
  const sideY = floorY + h * 0.09;
  api.add(api.cylinder(railR * 0.72, railR * 0.72, h * 0.18, 8).translate(-chuteWidth * 0.53, sideY, z), accentMat);
  api.add(api.cylinder(railR * 0.72, railR * 0.72, h * 0.18, 8).translate(chuteWidth * 0.53, sideY, z), accentMat);
}
const endZ = chuteStartZ + chuteLen;
api.add(api.box(chuteWidth * 1.13, h * 0.055, h * 0.28).translate(0, h * 0.085, endZ + h * 0.12), chuteMat);
for (let sx = -1; sx <= 1; sx += 2) {
  api.add(api.cylinder(railR * 1.7, railR * 1.9, h * 0.055, 10).translate(sx * postX, h * 0.0275, postZ), gripMat);
  api.add(api.cylinder(railR * 1.7, railR * 1.9, h * 0.055, 10).translate(sx * ladderDx, h * 0.0275, ladderBottomZ), gripMat);
}
api.collider({ kind: 'box', halfExtents: [w * 0.67, deckT * 0.5, w * 0.575], offset: [0, h, 0] });
for (let sx = -1; sx <= 1; sx += 2) {
  api.collider({ kind: 'cylinder', radius: railR * 1.35, halfHeight: h * 0.5, offset: [sx * postX, h * 0.5, postZ] });
}
return api.build();
